export interface BuiltinPromptEntry {
    sourceKey: string;       // 内置锚点：DB 记录凭它关联「恢复默认」
    category: PromptCategory;
    name: string;            // 展示名
    content: string;         // 运行时形态的默认正文（含占位符）
    order: number;           // 同分类内的展示/注入顺序（百位 = 分类段）
    mutable: boolean;        // true=面向用户的成段文案（停用=不注入）；false=技术模板（停用=回退默认）
    builtinVersion: number;  // 内置内容版本；未来升级内置文案时 +1，用于检测自定义漂移
}

