/** 按 sourceKey 取内置条目（找不到返回 undefined —— 调用方自行兜底）。 */
export const getBuiltinEntry = (sourceKey: string): BuiltinPromptEntry | undefined =>
    BUILTIN_PROMPT_ENTRIES.find((e) => e.sourceKey === sourceKey);

/** 取内置默认正文（按 sourceKey；无登记返回空串）。 */
export const getBuiltinContent = (sourceKey: string): string =>
    getBuiltinEntry(sourceKey)?.content ?? '';

/**
 * 内置占位符替换的公共小工具：{{char}} / {{user}} 全量替换。
 * __XXX__ 动态段不在这一层处理（各渲染函数按自己的数据语义填充）。
 */
export const fillIdentity = (text: string, charName: string, userName?: string): string =>
    text.replace(/\{\{char\}\}/g, charName).replace(/\{\{user\}\}/g, userName || '对方');